    echo '<script>window.greenResponsibilityPermission=' . json_encode(['edit' => !empty($permission['pode_editar']), 'include' => !empty($permission['pode_incluir']), 'delete' => !empty($permission['pode_excluir'])], JSON_UNESCAPED_SLASHES) . ';</script><script src="../assets/js/responsabilidades-permissoes.js?v=3"></script>';
});
