$context = $call('CALL sp_crud_select(:tabela,:filtros,NULL,1,0)', ['tabela' => 'infraestrutura', 'filtros' => $json(['CODINFRAESTRUTURA' => $id])])[0] ?? [];
if (!$context) { http_response_code(404); exit(IdiomaService::t('responsabilidades.erro.infraestrutura_nao_localizada', ['pt' => 'Infraestrutura não localizada.', 'en' => 'Infrastructure not found.', 'es' => 'Infraestructura no encontrada.'])); }
$types = $call('CALL sp_crud_select(:tabela,:filtros,NULL,100,0)', ['tabela' => 'vw_responsabilidade_tipos', 'filtros' => $json(['MODULO_CODIGO' => 'INFRAESTRUTURA', 'ATIVO' => 1])]);
