            $data = ['CODMODULO' => $moduleId, 'ORIGEM' => 'DIRETA', 'CODTIPORESPONSABILIDADE' => $typeId, 'CODCATEGORIARESPONSABILIDADE' => null, 'ENTIDADE' => 'infraestrutura', 'REGISTRO_ID' => (string)$id, 'TIPO_DESTINO' => 'USUARIO', 'CODUSUARIO' => $userId, 'CODGRUPO' => null, 'PRIORIDADE' => (int)($row['PRIORIDADE'] ?? 0), 'PRINCIPAL' => !empty($row['PRINCIPAL']) ? 1 : 0, 'VALIDO_DE' => trim((string)($row['VALIDO_DE'] ?? '')) ?: date('Y-m-d'), 'VALIDO_ATE' => trim((string)($row['VALIDO_ATE'] ?? '')) ?: null, 'ATIVO' => 1, 'CODUSUARIOALTERACAO' => (int)$_SESSION['usuario']['codusuario']];
            if ($assignmentId) $call('CALL sp_crud_update(:tabela,:chave,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'chave' => $json(['CODATRIBUICAO' => $assignmentId]), 'dados' => $json($data)]);
            else $call('CALL sp_crud_insert(:tabela,:dados)', ['tabela' => 'responsabilidade_atribuicoes', 'dados' => $json($data)]);
        }
        $message = $ignored ? IdiomaService::t('responsabilidades.msg.parcial', ['pt' => 'Operação concluída. Alterações não autorizadas foram ignoradas.', 'en' => 'Done. Unauthorized changes were ignored.', 'es' => 'Operación concluida. Los cambios no autorizados se ignoraron.']) : IdiomaService::t('responsabilidades.msg.salvas', ['pt' => 'Responsabilidades salvas com sucesso.', 'en' => 'Responsibilities saved successfully.', 'es' => 'Responsabilidades guardadas con éxito.']);
    } catch (Throwable $x) { $error = IdiomaService::t('responsabilidades.erro.salvar', ['pt' => 'Não foi possível salvar as responsabilidades. Verifique os dados informados.', 'en' => 'Could not save the responsibilities. Check the data entered.', 'es' => 'No fue posible guardar las responsabilidades. Verifique los datos informados.']); }
}
