){var table=document.querySelector('#infraestruturaResponsibilityTable tbody'),types=<?= json_encode($types, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,users=<?= json_encode($users, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,seq=0;function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');}function opts(items,id){return '<option value=""><?= htmlspecialchars(IdiomaService::t('responsabilidades.selecione', ['pt' => 'Selecione', 'en' => 'Select', 'es' => 'Seleccione']), ENT_QUOTES, 'UTF-8') ?></option>'+items.map(function(x){return '<option value="'+esc(x[id])+'">'+esc(x.NOME)+'</option>';}).join('');}document.querySelector('#addInfraestruturaResponsibility')?.addEventListener('click',function(){var key='novo_'+(++seq),row=document.createElement('tr');row.innerHTML='<td><select class="form-select form-select-sm" name="rows['+key+'][CODTIPORESPONSABILIDADE]">'+types.map(function(x){return '<option value="'+x.CODTIPORESPONSABILIDADE+'">'+esc(x.NOME)+'</option>';}).join('')+'</select></td><td><select class="form-select form-select-sm" name="rows['+key+'][CODUSUARIO]">'+opts(users,'CODUSUARIO')+'</select></td><td><input class="form-control form-control-sm" type="number" min="0" name="rows['+key+'][PRIORIDADE]" value="0"></td><td class="text-center"><input type="checkbox" name="rows['+key+'][PRINCIPAL]" value="1"></td><td><div class="d-flex gap-1"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_DE]" value="<?= date('Y-m-d') ?>"><input class="form-control form-control-sm" type="date" name="rows['+key+'][VALIDO_ATE]" value=""></div></td><td><button type="button" class="btn btn-sm btn-outline-danger js-delete-row"><i class="bi bi-trash"></i></button></td>';table.appendChild(row);});document.addEventListener('click',function(event){var button=event.target.closest('.js-delete-row');if(!button)return;var row=button.closest('tr'),key=row&&row.getAttribute('data-row-key');if(key){var hidden=document.createElement('input');hidden.type='hidden';hidden.name='rows['+key+'][_delete]';hidden.value='1';row.appendChild(hidden);}row?.remove();event.preventDefault();},true);});</script></body></html>
